(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  let wy = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  wx += Math.sin((x + y) * 0.008 + t * 0.15) * 20 + Math.cos((x - y * 2) * 0.006 - t * 0.1) * 12;
  wy += Math.cos((x - y) * 0.009 - t * 0.12) * 18 + Math.sin((y * 2 - x) * 0.007 + t * 0.18) * 14;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8]
  ];
  let aS = 0, iS = 0, aS2 = 0, iS2 = 0;
  for (let si = 0; si < src.length; si++) {
    const [sX, sY, f, sp] = src[si];
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w1 = Math.sin(d*f - t*sp), w2 = Math.cos(d*f*0.7 + t*sp*0.6 + 1.5);
    const coupling = si < 6 ? 1.0 : 0.6;
    aS += w1 * coupling; iS += w2 * coupling;
    aS2 += Math.sin(d*f*1.5 - t*sp*1.3 + si*0.8) * coupling;
    iS2 += Math.cos(d*f*0.5 + t*sp*0.4 + si*1.2) * coupling;
  }
  const act = aS/6.2, inh = iS/6.2, act2 = aS2/6.2, inh2 = iS2/6.2;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15 + Math.cos(sx*0.05-sy*0.09+t*1.4)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.07-ang*2+t*0.9)*0.2 + Math.cos(dist*0.03+ang*5-t*2.1)*0.15;
  const reaction1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const reaction2 = Math.tanh((act2 - inh2*0.6 + bg*0.25 - spiral*0.4)*2.0);
  const crossFeed = Math.sin(reaction1*reaction2*Math.PI*2)*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const fineDetail = (Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5))*0.08*Math.abs(reaction1);
  const blend = reaction1*0.45 + reaction2*0.25 + cell*0.15 + crossFeed*0.1 + fineDetail*0.05;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,40,85],[14,75,115],[18,120,135],[30,160,145],
    [90,185,130],[180,195,80],[220,170,60],[230,130,55],[210,85,60],
    [175,50,65],[120,25,55],[60,15,45],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(reaction1*Math.PI)*0.12+Math.sin(reaction2*Math.PI)*0.06;
